import{A as e,E as t,d as n,l as r,p as i}from"./runtime-core.esm-bundler-tCF-J6l5.js";import{t as a}from"./app-ybrB4hSf.js";var o=JSON.parse(`{"path":"/%E5%90%8E%E7%AB%AF%E5%BC%80%E5%8F%91/%E6%95%B0%E6%8D%AE%E5%BA%93/PostgreSQL/03_%E8%BF%90%E7%BB%B4%E7%AF%87/03_%E6%80%A7%E8%83%BD%E8%B0%83%E4%BC%98.html","title":"性能调优","lang":"zh-CN","frontmatter":{"title":"性能调优","order":3,"category":["数据库","PostgreSQL"],"tag":["PostgreSQL","运维","性能调优","pg_stat_statements","PgBouncer"]},"git":{"createdTime":1780573763000,"updatedTime":1780573763000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":9.5,"words":2851},"filePathRelative":"后端开发/数据库/PostgreSQL/03_运维篇/03_性能调优.md"}`),s={name:`03_性能调优.md`};function c(a,o,s,c,l,u){let d=e(`Mermaid`);return t(),r(`div`,null,[o[0]||=n(`<h1 id="性能调优" tabindex="-1"><a class="header-anchor" href="#性能调优"><span>性能调优</span></a></h1><p>&quot;数据库慢&quot;往往不是数据库本身的问题，而是配置不合理、查询未优化、连接管理混乱的综合结果。PostgreSQL 提供了丰富的观测工具和调优参数，本篇从<strong>观测 → 参数 → 连接池 → 案例</strong>四步走，建立系统化的调优方法论。</p><h2 id="一、观测先行-——-pg-stat-statements" tabindex="-1"><a class="header-anchor" href="#一、观测先行-——-pg-stat-statements"><span>一、观测先行 —— pg_stat_statements</span></a></h2><p>调优的第一步不是改参数，而是<strong>找到瓶颈</strong>。<code>pg_stat_statements</code> 是 PostgreSQL 最重要的性能观测扩展。</p><h3 id="_1-1-启用-pg-stat-statements" tabindex="-1"><a class="header-anchor" href="#_1-1-启用-pg-stat-statements"><span>1.1 启用 pg_stat_statements</span></a></h3><div class="language-ini line-numbers-mode" data-highlighter="shiki" data-ext="ini" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-ini"><span class="line"><span style="color:#7F848E;font-style:italic;"># postgresql.conf</span></span>
<span class="line"><span style="color:#C678DD;">shared_preload_libraries</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> &#39;pg_stat_statements&#39;</span></span>
<span class="line"><span style="color:#C678DD;">pg_stat_statements.max</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 10000       </span><span style="color:#7F848E;font-style:italic;"># 最多记录多少条 SQL</span></span>
<span class="line"><span style="color:#C678DD;">pg_stat_statements.track</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> all       </span><span style="color:#7F848E;font-style:italic;"># 跟踪所有 SQL（含 PL/pgSQL 内部）</span></span>
<span class="line"><span style="color:#C678DD;">pg_stat_statements.track_utility</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> on  </span><span style="color:#7F848E;font-style:italic;"># 跟踪 UTILITY 语句（CREATE/SET 等）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 重启后创建扩展</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> EXTENSION pg_stat_statements;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_1-2-定位慢查询" tabindex="-1"><a class="header-anchor" href="#_1-2-定位慢查询"><span>1.2 定位慢查询</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 按 总执行时间 排序（找到最耗时的 SQL）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> query, calls, total_exec_time, mean_exec_time,</span></span>
<span class="line"><span style="color:#C678DD;">       rows</span><span style="color:#ABB2BF;">, shared_blks_hit, shared_blks_read</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_stat_statements</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> total_exec_time </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#C678DD;">LIMIT</span><span style="color:#D19A66;"> 10</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 按 平均执行时间 排序（找到单次最慢的 SQL）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> query, calls, mean_exec_time, max_exec_time</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_stat_statements</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> mean_exec_time </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#C678DD;">LIMIT</span><span style="color:#D19A66;"> 10</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 按 IO 读取量排序（找到磁盘 IO 最重的 SQL）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> query, calls, shared_blks_read,</span></span>
<span class="line"><span style="color:#ABB2BF;">       shared_blks_hit,</span></span>
<span class="line"><span style="color:#56B6C2;">       round</span><span style="color:#ABB2BF;">(shared_blks_read::</span><span style="color:#C678DD;">numeric</span><span style="color:#ABB2BF;"> / </span><span style="color:#56B6C2;">nullif</span><span style="color:#ABB2BF;">(shared_blks_hit + shared_blks_read, </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">) * </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> cache_miss_ratio</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_stat_statements</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> shared_blks_read </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#C678DD;">LIMIT</span><span style="color:#D19A66;"> 10</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">重置统计</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 清零重新统计（调整参数或排查后重置）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> pg_stat_statements_reset();</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div></div><h2 id="二、关键参数调优" tabindex="-1"><a class="header-anchor" href="#二、关键参数调优"><span>二、关键参数调优</span></a></h2><p>PostgreSQL 有 300+ 参数，但真正需要调的只有十来个。以下是最影响性能的核心参数及其推荐值。</p>`,12),i(d,{code:``}),o[1]||=n(`<h3 id="_2-1-shared-buffers-——-共享缓冲区" tabindex="-1"><a class="header-anchor" href="#_2-1-shared-buffers-——-共享缓冲区"><span>2.1 shared_buffers —— 共享缓冲区</span></a></h3><div class="language-ini line-numbers-mode" data-highlighter="shiki" data-ext="ini" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-ini"><span class="line"><span style="color:#7F848E;font-style:italic;"># 推荐值：物理内存的 25%，上限约 8GB（超过后 OS 页缓存更有价值）</span></span>
<span class="line"><span style="color:#C678DD;">shared_buffers</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> &#39;4GB&#39;</span><span style="color:#7F848E;font-style:italic;">       # 16GB RAM 机器</span></span>
<span class="line"><span style="color:#C678DD;">shared_buffers</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> &#39;8GB&#39;</span><span style="color:#7F848E;font-style:italic;">       # 32GB RAM 机器</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看缓冲区命中率（应 &gt; 99%）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span></span>
<span class="line"><span style="color:#56B6C2;">    sum</span><span style="color:#ABB2BF;">(heap_blks_hit) / (</span><span style="color:#56B6C2;">sum</span><span style="color:#ABB2BF;">(heap_blks_hit) + </span><span style="color:#56B6C2;">sum</span><span style="color:#ABB2BF;">(heap_blks_read)) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> cache_hit_ratio</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_statio_user_tables;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">shared_buffers 不是越大越好</p><p>PostgreSQL 依赖操作系统的页缓存做二级缓存。<code>shared_buffers</code> 过大反而会导致：</p><ul><li>双重缓存浪费内存</li><li>checkpoint 时刷盘压力大</li><li>一般不超过物理内存的 40%</li></ul></div><h3 id="_2-2-effective-cache-size-——-查询规划器参考值" tabindex="-1"><a class="header-anchor" href="#_2-2-effective-cache-size-——-查询规划器参考值"><span>2.2 effective_cache_size —— 查询规划器参考值</span></a></h3><div class="language-ini line-numbers-mode" data-highlighter="shiki" data-ext="ini" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-ini"><span class="line"><span style="color:#7F848E;font-style:italic;"># 推荐值：物理内存的 75%（包含 shared_buffers + OS 页缓存）</span></span>
<span class="line"><span style="color:#C678DD;">effective_cache_size</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> &#39;12GB&#39;</span><span style="color:#7F848E;font-style:italic;">   # 16GB RAM 机器</span></span>
<span class="line"><span style="color:#C678DD;">effective_cache_size</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> &#39;24GB&#39;</span><span style="color:#7F848E;font-style:italic;">   # 32GB RAM 机器</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这个参数<strong>不分配内存</strong>，只是告诉规划器&quot;系统大概有多少缓存可用&quot;。值越大，规划器越倾向于使用索引扫描而非顺序扫描。</p><h3 id="_2-3-work-mem-——-排序和哈希操作内存" tabindex="-1"><a class="header-anchor" href="#_2-3-work-mem-——-排序和哈希操作内存"><span>2.3 work_mem —— 排序和哈希操作内存</span></a></h3><div class="language-ini line-numbers-mode" data-highlighter="shiki" data-ext="ini" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-ini"><span class="line"><span style="color:#7F848E;font-style:italic;"># 默认 4MB，通常偏小</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 估算公式：RAM / max_connections / 4（粗略）</span></span>
<span class="line"><span style="color:#C678DD;">work_mem</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> &#39;64MB&#39;</span><span style="color:#7F848E;font-style:italic;">    # 16GB RAM, 100 连接</span></span>
<span class="line"><span style="color:#C678DD;">work_mem</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> &#39;128MB&#39;</span><span style="color:#7F848E;font-style:italic;">   # 32GB RAM, 100 连接</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 检查是否有排序溢出到磁盘</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> query, calls, total_exec_time,</span></span>
<span class="line"><span style="color:#ABB2BF;">       sorts_spilled  </span><span style="color:#7F848E;font-style:italic;">-- 溢出到磁盘的排序次数</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_stat_statements</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> sorts_spilled </span><span style="color:#56B6C2;">&gt;</span><span style="color:#D19A66;"> 0</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> sorts_spilled </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">work_mem 的陷阱</p><p><code>work_mem</code> 是<strong>每个操作</strong>的内存上限，一个复杂查询可能同时使用多个 work_mem（ORDER BY + JOIN + 子查询）。设太大会导致 OOM。建议：</p><ol><li>全局设保守值（如 64MB）</li><li>大查询会话级调高：<code>SET LOCAL work_mem = &#39;256MB&#39;</code></li></ol></div><h3 id="_2-4-其他关键参数" tabindex="-1"><a class="header-anchor" href="#_2-4-其他关键参数"><span>2.4 其他关键参数</span></a></h3><div class="language-ini line-numbers-mode" data-highlighter="shiki" data-ext="ini" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-ini"><span class="line"><span style="color:#7F848E;font-style:italic;"># maintenance_work_mem —— VACUUM / CREATE INDEX 使用的内存</span></span>
<span class="line"><span style="color:#C678DD;">maintenance_work_mem</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> &#39;2GB&#39;</span><span style="color:#7F848E;font-style:italic;">     # 默认 64MB 太小，大表 VACUUM 很慢</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># wal_buffers —— WAL 缓冲区</span></span>
<span class="line"><span style="color:#C678DD;">wal_buffers</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> &#39;64MB&#39;</span><span style="color:#7F848E;font-style:italic;">             # 默认 -1（auto），通常 auto 就够了</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># checkpoint_completion_target —— checkpoint 分摊时间</span></span>
<span class="line"><span style="color:#C678DD;">checkpoint_completion_target</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 0.9   </span><span style="color:#7F848E;font-style:italic;"># 在 90% 的间隔内分摊写入</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># random_page_cost —— 随机 IO 代价</span></span>
<span class="line"><span style="color:#C678DD;">random_page_cost</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 1.1           </span><span style="color:#7F848E;font-style:italic;"># SSD 设 1.1（默认 4.0 是为 HDD）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 1.1 接近 seq_page_cost(1.0)，让规划器更倾向索引扫描</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># effective_io_concurrency —— 预取并发</span></span>
<span class="line"><span style="color:#C678DD;">effective_io_concurrency</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 200   </span><span style="color:#7F848E;font-style:italic;"># SSD 设 200，HDD 设 2</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># max_parallel_workers_per_gather —— 并行查询 worker 数</span></span>
<span class="line"><span style="color:#C678DD;">max_parallel_workers_per_gather</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 4   </span><span style="color:#7F848E;font-style:italic;"># 默认 2，多核可提高</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># max_parallel_workers —— 总并行 worker 上限</span></span>
<span class="line"><span style="color:#C678DD;">max_parallel_workers</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 8</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-5-参数速查表" tabindex="-1"><a class="header-anchor" href="#_2-5-参数速查表"><span>2.5 参数速查表</span></a></h3><table><thead><tr><th>参数</th><th>默认值</th><th>推荐值（16GB RAM）</th><th>说明</th></tr></thead><tbody><tr><td><code>shared_buffers</code></td><td>128MB</td><td>4GB</td><td>共享缓冲区</td></tr><tr><td><code>effective_cache_size</code></td><td>4GB</td><td>12GB</td><td>规划器缓存参考</td></tr><tr><td><code>work_mem</code></td><td>4MB</td><td>64MB</td><td>排序/哈希内存</td></tr><tr><td><code>maintenance_work_mem</code></td><td>64MB</td><td>2GB</td><td>维护操作内存</td></tr><tr><td><code>wal_buffers</code></td><td>auto</td><td>64MB</td><td>WAL 缓冲区</td></tr><tr><td><code>random_page_cost</code></td><td>4.0</td><td>1.1（SSD）</td><td>随机 IO 代价</td></tr><tr><td><code>checkpoint_completion_target</code></td><td>0.9</td><td>0.9</td><td>checkpoint 分摊</td></tr><tr><td><code>max_parallel_workers_per_gather</code></td><td>2</td><td>4</td><td>并行查询 worker</td></tr></tbody></table><h2 id="三、连接池-——-pgbouncer" tabindex="-1"><a class="header-anchor" href="#三、连接池-——-pgbouncer"><span>三、连接池 —— PgBouncer</span></a></h2><p>PostgreSQL 的每个连接都是一个 OS 进程（<code>fork</code>），连接数过多会严重拖慢性能。</p>`,17),i(d,{code:`eJxLy8kvT85ILCpR8AniUgCC4tKk9KLEggyFp+sWPevY/nz1erAwCDgbRjsWFCi82D/7+YpuBcNYhIQRsoQRkoQxsoSfTVKRvp2enp6hgYGBwpMdq17sn/esbylEeWpeCheqAwLSnfJL85JTi+DGBURDdDzbuABsFNgcuDshcmCJR22TFICSCgHuQLvx2pFfXJJelBoc6AO3JNgw+umEPrB56P4MNkKVQvJpsDGaLgMDNDudDRV0de0UAiAcI2SOMRInAMwONkTmGCFzjLkAw6+UkQ==`}),o[2]||=n(`<h3 id="_3-1-pgbouncer-配置" tabindex="-1"><a class="header-anchor" href="#_3-1-pgbouncer-配置"><span>3.1 PgBouncer 配置</span></a></h3><div class="language-ini line-numbers-mode" data-highlighter="shiki" data-ext="ini" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-ini"><span class="line"><span style="color:#7F848E;font-style:italic;"># pgbouncer.ini</span></span>
<span class="line"><span style="color:#61AFEF;">[databases]</span></span>
<span class="line"><span style="color:#C678DD;">mydb</span><span style="color:#ABB2BF;"> =</span><span style="color:#C678DD;"> host</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">127.0.0.1 </span><span style="color:#C678DD;">port</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">5432 </span><span style="color:#C678DD;">dbname</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">mydb</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">[pgbouncer]</span></span>
<span class="line"><span style="color:#C678DD;">listen_addr</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 0.0.0.0</span></span>
<span class="line"><span style="color:#C678DD;">listen_port</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 6432</span></span>
<span class="line"><span style="color:#C678DD;">auth_type</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> md5</span></span>
<span class="line"><span style="color:#C678DD;">auth_file</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> /etc/pgbouncer/userlist.txt</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">; 池化模式</span></span>
<span class="line"><span style="color:#C678DD;">pool_mode</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> transaction</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">; 连接数配置</span></span>
<span class="line"><span style="color:#C678DD;">max_client_conn</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 1000</span></span>
<span class="line"><span style="color:#C678DD;">default_pool_size</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 20        </span><span style="color:#7F848E;font-style:italic;">; 每个 database/user 的服务端连接数</span></span>
<span class="line"><span style="color:#C678DD;">reserve_pool_size</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 5         </span><span style="color:#7F848E;font-style:italic;">; 突发时额外连接</span></span>
<span class="line"><span style="color:#C678DD;">reserve_pool_timeout</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 3      </span><span style="color:#7F848E;font-style:italic;">; 等待额外连接的超时（秒）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">; 超时</span></span>
<span class="line"><span style="color:#C678DD;">server_idle_timeout</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 300     </span><span style="color:#7F848E;font-style:italic;">; 空闲连接 5 分钟回收</span></span>
<span class="line"><span style="color:#C678DD;">client_idle_timeout</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 0       </span><span style="color:#7F848E;font-style:italic;">; 客户端空闲不限</span></span>
<span class="line"><span style="color:#C678DD;">query_timeout</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 30            </span><span style="color:#7F848E;font-style:italic;">; 查询超时 30 秒</span></span>
<span class="line"><span style="color:#C678DD;">query_wait_timeout</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 60       </span><span style="color:#7F848E;font-style:italic;">; 等待连接超时 60 私</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">; 日志</span></span>
<span class="line"><span style="color:#C678DD;">log_connections</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 0</span></span>
<span class="line"><span style="color:#C678DD;">log_disconnections</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 0</span></span>
<span class="line"><span style="color:#C678DD;">stats_period</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 60</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-2-三种池化模式对比" tabindex="-1"><a class="header-anchor" href="#_3-2-三种池化模式对比"><span>3.2 三种池化模式对比</span></a></h3><table><thead><tr><th>模式</th><th>释放时机</th><th>事务支持</th><th>适用场景</th></tr></thead><tbody><tr><td>session</td><td>客户端断开</td><td>完整</td><td>兼容性要求高</td></tr><tr><td>transaction</td><td>事务结束</td><td>完整</td><td>Web 应用（推荐）</td></tr><tr><td>statement</td><td>语句结束</td><td>不支持</td><td>纯查询、无事务</td></tr></tbody></table><div class="hint-container important"><p class="hint-container-title">transaction 模式的限制</p><ul><li><code>SET</code> / <code>PREPARE</code> / <code>LISTEN</code> / <code>NOTIFY</code> 等会话级操作在事务结束后状态丢失</li><li>需要会话级状态的应用不适合 transaction 模式</li><li>Supabase 等云服务默认使用 transaction 模式，通过 <code>SET LOCAL</code> 替代 <code>SET</code> 解决</li></ul></div><h3 id="_3-3-pgbouncer-监控" tabindex="-1"><a class="header-anchor" href="#_3-3-pgbouncer-监控"><span>3.3 PgBouncer 监控</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 通过 admin 数据库查看状态</span></span>
<span class="line"><span style="color:#61AFEF;">psql</span><span style="color:#D19A66;"> -h</span><span style="color:#D19A66;"> 127.0.0.1</span><span style="color:#D19A66;"> -p</span><span style="color:#D19A66;"> 6432</span><span style="color:#D19A66;"> -U</span><span style="color:#98C379;"> pgbouncer</span><span style="color:#98C379;"> pgbouncer</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 常用命令</span></span>
<span class="line"><span style="color:#61AFEF;">SHOW</span><span style="color:#98C379;"> POOLS</span><span style="color:#ABB2BF;">;        </span><span style="color:#7F848E;font-style:italic;"># 查看连接池状态</span></span>
<span class="line"><span style="color:#61AFEF;">SHOW</span><span style="color:#98C379;"> STATS</span><span style="color:#ABB2BF;">;        </span><span style="color:#7F848E;font-style:italic;"># 查询统计</span></span>
<span class="line"><span style="color:#61AFEF;">SHOW</span><span style="color:#98C379;"> CLIENTS</span><span style="color:#ABB2BF;">;      </span><span style="color:#7F848E;font-style:italic;"># 客户端连接</span></span>
<span class="line"><span style="color:#61AFEF;">SHOW</span><span style="color:#98C379;"> SERVERS</span><span style="color:#ABB2BF;">;      </span><span style="color:#7F848E;font-style:italic;"># 服务端连接</span></span>
<span class="line"><span style="color:#61AFEF;">SHOW</span><span style="color:#98C379;"> DATABASES</span><span style="color:#ABB2BF;">;    </span><span style="color:#7F848E;font-style:italic;"># 数据库配置</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="四、运行时诊断" tabindex="-1"><a class="header-anchor" href="#四、运行时诊断"><span>四、运行时诊断</span></a></h2><h3 id="_4-1-pg-stat-activity-——-活跃连接" tabindex="-1"><a class="header-anchor" href="#_4-1-pg-stat-activity-——-活跃连接"><span>4.1 pg_stat_activity —— 活跃连接</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看当前所有连接和状态</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> pid, datname, usename, </span><span style="color:#C678DD;">state</span><span style="color:#ABB2BF;">, wait_event_type, wait_event,</span></span>
<span class="line"><span style="color:#ABB2BF;">       query, </span><span style="color:#C678DD;">now</span><span style="color:#ABB2BF;">() - query_start </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> duration</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_stat_activity</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> state</span><span style="color:#56B6C2;"> !=</span><span style="color:#98C379;"> &#39;idle&#39;</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> duration </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查找长时间运行的查询（超过 5 分钟）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> pid, usename, query, </span><span style="color:#C678DD;">now</span><span style="color:#ABB2BF;">() - query_start </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> duration</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_stat_activity</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> state</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;active&#39;</span></span>
<span class="line"><span style="color:#C678DD;">  AND</span><span style="color:#C678DD;"> now</span><span style="color:#ABB2BF;">() - query_start </span><span style="color:#56B6C2;">&gt;</span><span style="color:#ABB2BF;"> interval </span><span style="color:#98C379;">&#39;5 minutes&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 终止问题查询</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> pg_cancel_backend(pid);       </span><span style="color:#7F848E;font-style:italic;">-- 发送 SIGINT，温和终止</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> pg_terminate_backend(pid);    </span><span style="color:#7F848E;font-style:italic;">-- 发送 SIGTERM，强制终止</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-2-pg-stat-user-tables-——-表级统计" tabindex="-1"><a class="header-anchor" href="#_4-2-pg-stat-user-tables-——-表级统计"><span>4.2 pg_stat_user_tables —— 表级统计</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看表的顺序扫描 vs 索引扫描</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> relname, seq_scan, idx_scan,</span></span>
<span class="line"><span style="color:#56B6C2;">       round</span><span style="color:#ABB2BF;">(idx_scan::</span><span style="color:#C678DD;">numeric</span><span style="color:#ABB2BF;"> / </span><span style="color:#56B6C2;">nullif</span><span style="color:#ABB2BF;">(seq_scan + idx_scan, </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">) * </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> idx_scan_ratio,</span></span>
<span class="line"><span style="color:#ABB2BF;">       n_live_tup, n_dead_tup</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_stat_user_tables</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> seq_scan </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看需要 VACUUM 的表（死元组比例高）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> relname, n_live_tup, n_dead_tup,</span></span>
<span class="line"><span style="color:#56B6C2;">       round</span><span style="color:#ABB2BF;">(n_dead_tup::</span><span style="color:#C678DD;">numeric</span><span style="color:#ABB2BF;"> / </span><span style="color:#56B6C2;">nullif</span><span style="color:#ABB2BF;">(n_live_tup + n_dead_tup, </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">) * </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> dead_ratio,</span></span>
<span class="line"><span style="color:#ABB2BF;">       last_vacuum, last_autovacuum, last_analyze, last_autoanalyze</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_stat_user_tables</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> n_dead_tup </span><span style="color:#56B6C2;">&gt;</span><span style="color:#D19A66;"> 10000</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> dead_ratio </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="五、vacuum-与-analyze-策略" tabindex="-1"><a class="header-anchor" href="#五、vacuum-与-analyze-策略"><span>五、VACUUM 与 ANALYZE 策略</span></a></h2><h3 id="_5-1-理解-vacuum" tabindex="-1"><a class="header-anchor" href="#_5-1-理解-vacuum"><span>5.1 理解 VACUUM</span></a></h3><p>PostgreSQL 的 MVCC 机制意味着 UPDATE 和 DELETE 不会立即回收空间，而是留下&quot;死元组&quot;（dead tuples）。VACUUM 负责清理这些死元组。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 手动 VACUUM 和 ANALYZE</span></span>
<span class="line"><span style="color:#ABB2BF;">VACUUM orders;                 </span><span style="color:#7F848E;font-style:italic;">-- 清理死元组，不回收磁盘空间给 OS</span></span>
<span class="line"><span style="color:#ABB2BF;">VACUUM FULL orders;            </span><span style="color:#7F848E;font-style:italic;">-- 重建表，回收空间给 OS（锁全表！生产慎用）</span></span>
<span class="line"><span style="color:#ABB2BF;">VACUUM ANALYZE orders;         </span><span style="color:#7F848E;font-style:italic;">-- 清理 + 更新统计信息</span></span>
<span class="line"><span style="color:#ABB2BF;">ANALYZE orders;                </span><span style="color:#7F848E;font-style:italic;">-- 只更新统计信息</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-2-自动清理调优" tabindex="-1"><a class="header-anchor" href="#_5-2-自动清理调优"><span>5.2 自动清理调优</span></a></h3><div class="language-ini line-numbers-mode" data-highlighter="shiki" data-ext="ini" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-ini"><span class="line"><span style="color:#7F848E;font-style:italic;"># postgresql.conf —— 自动清理参数</span></span>
<span class="line"><span style="color:#C678DD;">autovacuum</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> on                    </span><span style="color:#7F848E;font-style:italic;"># 必须开启</span></span>
<span class="line"><span style="color:#C678DD;">autovacuum_max_workers</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 4         </span><span style="color:#7F848E;font-style:italic;"># 清理 worker 数（默认 3）</span></span>
<span class="line"><span style="color:#C678DD;">autovacuum_naptime</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 30s           </span><span style="color:#7F848E;font-style:italic;"># 检查间隔（默认 1min）</span></span>
<span class="line"><span style="color:#C678DD;">log_autovacuum_min_duration</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 0    </span><span style="color:#7F848E;font-style:italic;"># 记录所有 autovacuum 操作</span></span>
<span class="line"></span>
<span class="line"><span style="color:#98C379;">-- 触发阈值（以表的行数百分比计算）</span></span>
<span class="line"><span style="color:#98C379;">-- </span><span style="color:#C678DD;">autovacuum_vacuum_scale_factor</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 0.2   -- 20% 行被更新/删除后触发</span></span>
<span class="line"><span style="color:#98C379;">-- </span><span style="color:#C678DD;">autovacuum_analyze_scale_factor</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 0.1  -- 10% 行变更后触发 ANALYZE</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 对大表设置绝对阈值（避免百分比在大表上触发太晚）</span></span>
<span class="line"><span style="color:#C678DD;">ALTER</span><span style="color:#C678DD;"> TABLE</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    autovacuum_vacuum_scale_factor </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    autovacuum_vacuum_threshold </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 100000</span><span style="color:#ABB2BF;">,      </span><span style="color:#7F848E;font-style:italic;">-- 10 万行变更即触发</span></span>
<span class="line"><span style="color:#ABB2BF;">    autovacuum_analyze_scale_factor </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    autovacuum_analyze_threshold </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 50000</span><span style="color:#7F848E;font-style:italic;">        -- 5 万行变更即 ANALYZE</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">VACUUM FULL 的代价</p><p><code>VACUUM FULL</code> 重建整张表并回收空间给 OS，但会持有<strong>ACCESS EXCLUSIVE 锁</strong>，期间该表完全不可读写。生产环境通常用 <code>pg_repack</code> 扩展替代，它可以在不锁表的情况下重建表。</p></div><h2 id="六、auto-explain-——-自动记录慢执行计划" tabindex="-1"><a class="header-anchor" href="#六、auto-explain-——-自动记录慢执行计划"><span>六、Auto-Explain —— 自动记录慢执行计划</span></a></h2><div class="language-ini line-numbers-mode" data-highlighter="shiki" data-ext="ini" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-ini"><span class="line"><span style="color:#7F848E;font-style:italic;"># postgresql.conf</span></span>
<span class="line"><span style="color:#C678DD;">shared_preload_libraries</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> &#39;auto_explain&#39;</span></span>
<span class="line"><span style="color:#C678DD;">auto_explain.log_min_duration</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> &#39;1s&#39;</span><span style="color:#7F848E;font-style:italic;">     # 记录超过 1 秒的查询计划</span></span>
<span class="line"><span style="color:#C678DD;">auto_explain.log_analyze</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> true           </span><span style="color:#7F848E;font-style:italic;"># 包含实际执行时间</span></span>
<span class="line"><span style="color:#C678DD;">auto_explain.log_buffers</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> true           </span><span style="color:#7F848E;font-style:italic;"># 包含 IO 信息</span></span>
<span class="line"><span style="color:#C678DD;">auto_explain.log_format</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> &#39;json&#39;</span><span style="color:#7F848E;font-style:italic;">          # JSON 格式，便于解析</span></span>
<span class="line"><span style="color:#C678DD;">auto_explain.log_nested_statements</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> true </span><span style="color:#7F848E;font-style:italic;"># 包含嵌套 SQL</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>也可以在会话级别启用：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">LOAD</span><span style="color:#98C379;"> &#39;auto_explain&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#D19A66;"> auto_explain</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">log_min_duration</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;500ms&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#D19A66;"> auto_explain</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">log_analyze</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> true;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="七、并行查询调优" tabindex="-1"><a class="header-anchor" href="#七、并行查询调优"><span>七、并行查询调优</span></a></h2><p>PostgreSQL 10+ 支持并行查询，大表扫描和聚合可显著加速。</p><div class="language-ini line-numbers-mode" data-highlighter="shiki" data-ext="ini" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-ini"><span class="line"><span style="color:#7F848E;font-style:italic;"># postgresql.conf</span></span>
<span class="line"><span style="color:#C678DD;">max_parallel_workers_per_gather</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 4    </span><span style="color:#7F848E;font-style:italic;"># 每个 Gather 节点的最大 worker</span></span>
<span class="line"><span style="color:#C678DD;">max_parallel_workers</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 8               </span><span style="color:#7F848E;font-style:italic;"># 总并行 worker 上限</span></span>
<span class="line"><span style="color:#C678DD;">max_parallel_maintenance_workers</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 4   </span><span style="color:#7F848E;font-style:italic;"># 维护操作并行度</span></span>
<span class="line"><span style="color:#C678DD;">parallel_tuple_cost</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 0.01             </span><span style="color:#7F848E;font-style:italic;"># worker 传输元组代价（越小越倾向并行）</span></span>
<span class="line"><span style="color:#C678DD;">parallel_setup_cost</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> 100              </span><span style="color:#7F848E;font-style:italic;"># 启动 worker 代价（越小越倾向并行）</span></span>
<span class="line"><span style="color:#C678DD;">min_parallel_table_scan_size</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> &#39;8MB&#39;</span><span style="color:#7F848E;font-style:italic;">   # 表小于此值不考虑并行</span></span>
<span class="line"><span style="color:#C678DD;">min_parallel_index_scan_size</span><span style="color:#ABB2BF;"> =</span><span style="color:#98C379;"> &#39;512kB&#39;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 检查查询是否使用了并行</span></span>
<span class="line"><span style="color:#ABB2BF;">EXPLAIN ANALYZE </span><span style="color:#C678DD;">SELECT</span><span style="color:#56B6C2;"> COUNT</span><span style="color:#ABB2BF;">(*) </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> created_at </span><span style="color:#56B6C2;">&gt;</span><span style="color:#98C379;"> &#39;2026-01-01&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 输出中看到 Gather 节点 + Workers 说明启用了并行</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Gather (actual rows=1, loops=1)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--   Workers Planned: 4, Workers Launched: 4</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--   -&gt;  Parallel Seq Scan on orders</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="八、实战案例" tabindex="-1"><a class="header-anchor" href="#八、实战案例"><span>八、实战案例</span></a></h2><h3 id="场景-电商订单查询从-12-秒优化到-50ms" tabindex="-1"><a class="header-anchor" href="#场景-电商订单查询从-12-秒优化到-50ms"><span>场景：电商订单查询从 12 秒优化到 50ms</span></a></h3><p><strong>症状</strong>：<code>SELECT * FROM orders WHERE user_id = ? AND status = &#39;paid&#39; ORDER BY created_at DESC LIMIT 20</code> 执行耗时 12 秒。</p><p><strong>第一步：诊断</strong></p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">EXPLAIN ANALYZE</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> user_id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 12345</span><span style="color:#C678DD;"> AND</span><span style="color:#C678DD;"> status</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;paid&#39;</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> created_at </span><span style="color:#C678DD;">DESC</span><span style="color:#C678DD;"> LIMIT</span><span style="color:#D19A66;"> 20</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 结果：Seq Scan on orders (cost=0.00..580000.00 rows=1 width=200)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 过滤条件选择性差，走了全表扫描</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>第二步：检查统计信息</strong></p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> relname, n_distinct, correlation</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_stats</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> tablename </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;orders&#39;</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> attname </span><span style="color:#C678DD;">IN</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;user_id&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;status&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- n_distinct: user_id = -0.1 (10% 唯一), status = 5</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 5 个状态值，选择性差</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>第三步：创建复合索引</strong></p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 创建覆盖索引（包含查询的所有列）</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_orders_user_status_created</span></span>
<span class="line"><span style="color:#C678DD;">ON</span><span style="color:#ABB2BF;"> orders (user_id, </span><span style="color:#C678DD;">status</span><span style="color:#ABB2BF;">, created_at </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 或者使用 INCLUDE 避免回表</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_orders_covering</span></span>
<span class="line"><span style="color:#C678DD;">ON</span><span style="color:#ABB2BF;"> orders (user_id, </span><span style="color:#C678DD;">status</span><span style="color:#ABB2BF;">, created_at </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">INCLUDE</span><span style="color:#ABB2BF;"> (order_no, amount, payment_method);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>第四步：参数调整</strong></p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 该查询涉及排序，增大 work_mem 减少磁盘排序</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> work_mem </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;128MB&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- SSD 机器降低随机 IO 代价</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> random_page_cost </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>第五步：验证</strong></p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">EXPLAIN ANALYZE</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> user_id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 12345</span><span style="color:#C678DD;"> AND</span><span style="color:#C678DD;"> status</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;paid&#39;</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> created_at </span><span style="color:#C678DD;">DESC</span><span style="color:#C678DD;"> LIMIT</span><span style="color:#D19A66;"> 20</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 结果：Index Scan using idx_orders_user_status_created</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- (cost=0.43..8.50 rows=20 width=200) (actual time=0.028..0.050 rows=20 loops=1)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 从 12s → 0.05ms，提升 240 倍</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>优化总结：</strong></p><table><thead><tr><th>优化手段</th><th>效果</th></tr></thead><tbody><tr><td>复合索引</td><td>消除全表扫描，命中索引</td></tr><tr><td>INCLUDE 覆盖列</td><td>避免回表，减少 IO</td></tr><tr><td>work_mem 调整</td><td>排序在内存完成，不溢出磁盘</td></tr><tr><td>random_page_cost = 1.1</td><td>SSD 环境下规划器更倾向索引</td></tr></tbody></table><h2 id="开源参考" tabindex="-1"><a class="header-anchor" href="#开源参考"><span>开源参考</span></a></h2><table><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://github.com/supabase/supabase" target="_blank" rel="noopener noreferrer">Supabase</a></td><td>基于 PG 的开源 Firebase，使用 PgBouncer 管理连接池，默认 transaction 模式</td></tr><tr><td><a href="https://github.com/PostgREST/postgrest" target="_blank" rel="noopener noreferrer">PostgREST</a></td><td>PG 自动 REST API，依赖 <code>pg_stat_statements</code> 做查询分析</td></tr></tbody></table><h2 id="面试技巧" tabindex="-1"><a class="header-anchor" href="#面试技巧"><span>面试技巧</span></a></h2><div class="hint-container tip"><p class="hint-container-title">面试高频问题</p><ol><li><p><strong>shared_buffers 为什么设 25% 而不是越大越好？</strong> PG 依赖 OS 页缓存做二级缓存，<code>shared_buffers</code> 过大会导致双重缓存浪费、checkpoint 压力大。超过 8GB 后收益递减。</p></li><li><p><strong>work_mem 设大了会有什么问题？</strong> <code>work_mem</code> 是<strong>每个操作</strong>的上限，一个查询可能有多个排序/哈希操作同时使用。1000 连接 × 4 个操作 × 256MB = 1TB 内存！必须全局保守、会话级调高。</p></li><li><p><strong>PgBouncer 三种模式的区别？</strong> 核心是连接释放时机：session 最安全但浪费连接，transaction 最均衡（推荐），statement 最省但不支持事务。面试时提一下 Supabase 默认 transaction 模式是加分项。</p></li><li><p><strong>如何判断一个查询需要优化？</strong> 四步法：① <code>pg_stat_statements</code> 找慢查询 → ② <code>EXPLAIN ANALYZE</code> 看执行计划 → ③ <code>pg_stats</code> 检查统计信息 → ④ 对症下药（索引/参数/SQL 改写）。</p></li><li><p><strong>VACUUM 和 VACUUM FULL 的区别？</strong> VACUUM 标记死元组可复用但不回收空间给 OS；VACUUM FULL 重建表回收空间但锁全表。生产用 <code>pg_repack</code> 替代 VACUUM FULL。</p></li></ol></div>`,47)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};